      pelaksanaNama: patient.petugasPJ || raw.pelaksanaNama || DEFAULT_PELAKSANA_NAMA,
      pelaksanaNIP: patient.nipPJ || raw.pelaksanaNIP || DEFAULT_PELAKSANA_NIP,
      statusPemantauan: patient.statusPemantauan || raw.statusPemantauan,
